<?php require_once __DIR__.'/../lib/app.php';$pageTitle='휴가유형 관리';include '_top.php';$pdo=db();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$d=[trim($_POST['name']),trim($_POST['code']),$_POST['color'],isset($_POST['deduct_enabled'])?1:0,(float)$_POST['default_days'],isset($_POST['allow_custom_days'])?1:0,(float)$_POST['min_unit'],isset($_POST['require_half_option'])?1:0,isset($_POST['allow_date_range'])?1:0,isset($_POST['include_weekends'])?1:0,isset($_POST['require_evidence'])?1:0,isset($_POST['require_approval'])?1:0,isset($_POST['apply_daily_limit'])?1:0,$_POST['annual_limit']!==''?$_POST['annual_limit']:null,isset($_POST['is_paid'])?1:0,(int)$_POST['sort_order'],isset($_POST['is_active'])?1:0,trim($_POST['description'])];$sql=$id?'UPDATE leave_types SET name=?,code=?,color=?,deduct_enabled=?,default_days=?,allow_custom_days=?,min_unit=?,require_half_option=?,allow_date_range=?,include_weekends=?,require_evidence=?,require_approval=?,apply_daily_limit=?,annual_limit=?,is_paid=?,sort_order=?,is_active=?,description=? WHERE id=?':'INSERT INTO leave_types(name,code,color,deduct_enabled,default_days,allow_custom_days,min_unit,require_half_option,allow_date_range,include_weekends,require_evidence,require_approval,apply_daily_limit,annual_limit,is_paid,sort_order,is_active,description) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)';$pdo->prepare($sql)->execute($id?[...$d,$id]:$d);$msg='저장되었습니다.';}$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM leave_types WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$rows=$pdo->query('SELECT * FROM leave_types ORDER BY sort_order,id')->fetchAll();function ck($e,$k,$default=1){return (!isset($e)?$default:!empty($e[$k]))?'checked':'';}?><h1>휴가유형 설정</h1><p class="muted">조합별 규정에 맞게 모든 휴가유형을 자유롭게 추가·수정합니다.</p><?php if($msg):?><div class="alert ok"><?=$msg?></div><?php endif?><div class="grid"><div class="col6 card"><h2><?= $edit?'유형 수정':'유형 추가'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=h($edit['id']??'')?>"><div class="grid"><label class="col6">휴가명<input name="name" required value="<?=h($edit['name']??'')?>"></label><label class="col6">코드<input name="code" required value="<?=h($edit['code']??'')?>"></label><label class="col4">색상<input type="color" name="color" value="<?=h($edit['color']??'#2563eb')?>"></label><label class="col4">기본일수<input type="number" step=".25" name="default_days" value="<?=h($edit['default_days']??1)?>"></label><label class="col4">최소단위<input type="number" step=".25" name="min_unit" value="<?=h($edit['min_unit']??.25)?>"></label><label class="col6">연간한도(빈칸=없음)<input type="number" step=".25" name="annual_limit" value="<?=h($edit['annual_limit']??'')?>"></label><label class="col6">표시순서<input type="number" name="sort_order" value="<?=h($edit['sort_order']??0)?>"></label></div><div class="grid"><label class="col4"><input style="width:auto" type="checkbox" name="deduct_enabled" <?=ck($edit,'deduct_enabled')?>> 연차차감</label><label class="col4"><input style="width:auto" type="checkbox" name="allow_custom_days" <?=ck($edit,'allow_custom_days')?>> 일수직접입력</label><label class="col4"><input style="width:auto" type="checkbox" name="require_half_option" <?=ck($edit,'require_half_option',0)?>> 오전/오후</label><label class="col4"><input style="width:auto" type="checkbox" name="allow_date_range" <?=ck($edit,'allow_date_range')?>> 기간신청</label><label class="col4"><input style="width:auto" type="checkbox" name="include_weekends" <?=ck($edit,'include_weekends',0)?>> 주말포함</label><label class="col4"><input style="width:auto" type="checkbox" name="require_evidence" <?=ck($edit,'require_evidence',0)?>> 증빙필수</label><label class="col4"><input style="width:auto" type="checkbox" name="require_approval" <?=ck($edit,'require_approval')?>> 결재필요</label><label class="col4"><input style="width:auto" type="checkbox" name="apply_daily_limit" <?=ck($edit,'apply_daily_limit')?>> 인원제한</label><label class="col4"><input style="width:auto" type="checkbox" name="is_paid" <?=ck($edit,'is_paid')?>> 유급</label><label class="col4"><input style="width:auto" type="checkbox" name="is_active" <?=ck($edit,'is_active')?>> 사용</label></div><label>설명<textarea name="description"><?=h($edit['description']??'')?></textarea></label><button class="btn">저장</button></form></div><div class="col6 card"><h2>등록 유형</h2><table class="table"><tr><th>유형</th><th>차감</th><th>결재</th><th>상태</th><th></th></tr><?php foreach($rows as $r):?><tr><td><span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:<?=h($r['color'])?>"></span> <?=h($r['name'])?></td><td><?=$r['deduct_enabled']?'차감':'미차감'?></td><td><?=$r['require_approval']?'필요':'자동승인'?></td><td><?=$r['is_active']?'사용':'중지'?></td><td><a class="btn sm gray" href="?edit=<?=$r['id']?>">수정</a></td></tr><?php endforeach?></table></div></div><?php include '_bottom.php';?>